const tableBody  = document.getElementById('tableBody');
const sourceLine = document.getElementById('sourceLine');
const canvas     = document.getElementById('barChart');
const ctx        = canvas.getContext('2d');

YEARS.forEach(y => { const o = document.createElement('option'); o.value = y; o.textContent = y; yearSelect.appendChild(o); });

function render(year) {
  const filtered = DATA.filter(d => d.year == year);
  tableBody.innerHTML = '';
  filtered.forEach(d => {
    const pct = ((+d.children_fully_immunised / +d.children_due) * 100).toFixed(1);
